head.script:
scwin.onpageload = function() {
    var jsonData = [{col1:"a"},{col1:"c"},{col1:"d"},{col1:"b"}];
    dataList1.setJSON(jsonData);
    gridView1.setFocusedCell(2,0,false);
};

scwin.onpageunload = function() {

};


scwin.cnt = 0;
scwin.dataList1_onrowpositionchange = function(info){
    console.log(scwin.cnt + " onrowpositionchange :::: oldRowIndex : " + info.oldRowIndex + " , newRowIndex : " + info.newRowIndex);
    scwin.cnt++;

};

scwin.dataList1_onbeforerowpositionchange = function(info){

    console.log(scwin.cnt + " onbeforerowpositionchange :::: oldRowIndex : " + info.oldRowIndex + " , newRowIndex : " + info.newRowIndex);
    scwin.cnt++;
    var data = dataList1.getCellData(info.oldRowIndex, 0);
    //debugger;
    if(data == "a"){
        console.log("aaa");

        requires("uiplugin.popup");

        var options = {
            id : "popup2_"+scwin.cnt,
            type : "wframePopup",    //browserPopup//wframePopup
            width: 300 + "px",
            height: 300 + "px",

            top: 100 + "px",
            left: 100 + "px",


            modal : true,
            useModalStack: true,

            className : "",

            style : "",

            resizable : true,
            status : false,
            menubar : false,
            scrollbars : false,
            title : false,
            useMaximize : true
        };
        $p.openPopup("",  options );


        return false;
    }
};

scwin.gridView1_onsort = function(info){
    console.log(scwin.cnt + " onsort :::: ");
    scwin.cnt++;
}
